7	const CLIP_HALF_WINDOW_SECS = 1.2;
8	const SPEED_KEY = 'td-clip-speed';
9	const SPEEDS = [0.25, 0.5, 1] as const;
10	type Speed = (typeof SPEEDS)[number];
11	
12	function loadSpeed(): Speed {
13	  const stored = Number(localStorage.getItem(SPEED_KEY));
14	  return (SPEEDS as readonly number[]).includes(stored) ? (stored as Speed) : 0.5;
15	}
