23	/**
24	 * A short, looping window of the real fight video around one labelled
25	 * event's frame, with the real FighterOverlay boxes/skeletons drawn on top —
26	 * reuses the same frame-numbering contract and requestVideoFrameCallback
27	 * draw loop as Player.tsx, just scoped to a ~2.4s window instead of the
28	 * whole fight.
29	 */
30	export default function ClipPlayer({ fight, frame, corner }: ClipPlayerProps) {
31	  const videoRef = useRef<HTMLVideoElement>(null);
32	  const overlayRef = useRef<FighterOverlayHandle>(null);
33	  const rafRef = useRef<number | null>(null);
34	  const [isPlaying, setIsPlaying] = useState(true);
35	  const [showBoxes, setShowBoxes] = useState(true);
36	  const [showSkeletons, setShowSkeletons] = useState(true);
37	  const [speed, setSpeed] = useState<Speed>(loadSpeed);
38	  const [currentTime, setCurrentTime] = useState(0);
39	
40	  useEffect(() => { localStorage.setItem(SPEED_KEY, String(speed)); }, [speed]);
41	
42	  const { frameMap } = useFighterFrames(fight.id);
43	  const { events: swapEvents } = useEvents(fight.id, { source: 'label', kind: 'corner_swap' });
44	  const cornerSwapSpans = swapEvents.map((e) => ({ frame: e.frame, end_frame: e.end_frame }));
45	
46	  const fps = fight.fps;
47	  const eventTime = (frame - 1) / fps;
48	  const windowStart = Math.max(0, eventTime - CLIP_HALF_WINDOW_SECS);
49	  const windowEnd = eventTime + CLIP_HALF_WINDOW_SECS;
50	
51	  // Jump to the event's window whenever the reviewed event changes.
52	  useEffect(() => {
53	    const video = videoRef.current;
54	    if (!video) return;
55	    const seek = () => {
56	      video.currentTime = windowStart;
57	      video.playbackRate = speed;
58	      setCurrentTime(windowStart);
59	      video.play().catch(() => {});
60	      setIsPlaying(true);
61	    };
62	    if (video.readyState >= 1) seek();
63	    else video.addEventListener('loadedmetadata', seek, { once: true });
64	    return () => video.removeEventListener('loadedmetadata', seek);
65	    // eslint-disable-next-line react-hooks/exhaustive-deps
66	  }, [fight.id, frame]);
67	
68	  useEffect(() => {
69	    const video = videoRef.current;
70	    if (video) video.playbackRate = speed;
71	  }, [speed]);
72	
73	  // Loop playback within [windowStart, windowEnd] and draw the overlay per frame.
74	  useEffect(() => {
75	    const video = videoRef.current;
76	    if (!video || !isPlaying) {
77	      if (rafRef.current !== null && video) {
78	        video.cancelVideoFrameCallback(rafRef.current);
79	        rafRef.current = null;
