83	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
84	      let t = metadata.mediaTime;
85	      if (t >= windowEnd) {
86	        video.currentTime = windowStart;
87	        t = windowStart;
88	      }
89	      overlayRef.current?.draw(Math.floor(t * fps) + 1);
90	      setCurrentTime(t);
91	      rafRef.current = video.requestVideoFrameCallback(tick);
92	    };
93	    rafRef.current = video.requestVideoFrameCallback(tick);
94	    return () => {
95	      if (rafRef.current !== null) video.cancelVideoFrameCallback(rafRef.current);
96	      rafRef.current = null;
97	    };
98	  }, [isPlaying, windowStart, windowEnd, fps]);
99	
100	  const togglePlay = useCallback(() => {
101	    const video = videoRef.current;
102	    if (!video) return;
103	    if (isPlaying) { video.pause(); setIsPlaying(false); } else { video.play().catch(() => {}); setIsPlaying(true); }
104	  }, [isPlaying]);
105	
106	  const handleScrub = (t: number) => {
107	    const video = videoRef.current;
108	    if (!video) return;
109	    video.pause();
110	    setIsPlaying(false);
111	    video.currentTime = t;
112	    setCurrentTime(t);
113	    overlayRef.current?.draw(Math.floor(t * fps) + 1);
114	  };
115	
116	  const stepFrame = useCallback((delta: number) => {
117	    const video = videoRef.current;
118	    if (!video) return;
119	    video.pause();
120	    setIsPlaying(false);
121	    const t = Math.min(Math.max(video.currentTime + delta / fps, windowStart), windowEnd);
122	    video.currentTime = t;
123	    setCurrentTime(t);
124	    overlayRef.current?.draw(Math.floor(t * fps) + 1);
125	  }, [fps, windowStart, windowEnd]);
126	
127	  const clipFrame = Math.floor((currentTime - windowStart) * fps) + 1;
128	  const clipFrames = Math.max(1, Math.round((windowEnd - windowStart) * fps));
129	
130	  return (
131	    <div>
132	      <div style={{ display: 'flex', alignItems: 'center', gap: 9, flexWrap: 'wrap', marginBottom: 10 }}>
133	        <button type="button" className={'pill' + (showSkeletons ? ' active' : '')} onClick={() => setShowSkeletons((v) => !v)} style={{ padding: '4px 10px', fontSize: 11 }}>Skeleton</button>
134	        <button type="button" className={'pill' + (showBoxes ? ' active' : '')} onClick={() => setShowBoxes((v) => !v)} style={{ padding: '4px 10px', fontSize: 11 }}>Box</button>
135	      </div>
136	
137	      <div style={{ position: 'relative', width: '100%', maxWidth: 720, margin: '0 auto', borderRadius: 12, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.07)', background: '#000' }}>
138	        <video
139	          ref={videoRef}
140	          src={`/fights/${fight.id}/video`}
141	          muted
142	          playsInline
143	          style={{ width: '100%', display: 'block' }}
144	          onPlay={() => setIsPlaying(true)}
145	          onPause={() => setIsPlaying(false)}
146	        />
147	        <FighterOverlay
148	          ref={overlayRef}
149	          frameMap={frameMap}
150	          fightWidth={fight.width}
151	          fightHeight={fight.height}
152	          showBoxes={showBoxes}
153	          showSkeletons={showSkeletons}
154	          highlightCorner={corner as 0 | 1 | null}
155	          dimUnhighlighted
156	          cornerSwapSpans={cornerSwapSpans}
157	        />
158	      </div>
159	
160	      <div style={{ display: 'flex', alignItems: 'center', gap: 11, flexWrap: 'wrap', marginTop: 11 }}>
161	        <button type="button" onClick={() => stepFrame(-1)} title="Previous frame" style={{ width: 28, height: 28, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
162	          <span className="material-symbols-outlined" style={{ fontSize: 15 }}>skip_previous</span>
163	        </button>
164	        <button type="button" className="lab-ibtn" onClick={togglePlay} title="Play / pause" style={{ width: 32, height: 32, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
165	          <span className="material-symbols-outlined" style={{ fontSize: 16 }}>{isPlaying ? 'pause' : 'play_arrow'}</span>
166	        </button>
167	        <button type="button" onClick={() => stepFrame(1)} title="Next frame" style={{ width: 28, height: 28, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
168	          <span className="material-symbols-outlined" style={{ fontSize: 15 }}>skip_next</span>
169	        </button>
170	        <input
171	          type="range"
172	          min={windowStart}
173	          max={windowEnd}
174	          step={1 / fps}
175	          value={currentTime}
176	          onChange={(e) => handleScrub(Number(e.target.value))}
177	          style={{ flex: 1, minWidth: 140, accentColor: 'var(--cyan-400)', height: 4 }}
178	          aria-label="Frame"
179	        />
180	        <span style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 11, fontWeight: 700, color: 'var(--text-muted)' }}>
181	          {String(Math.min(clipFrame, clipFrames)).padStart(2, '0')} / {clipFrames}
182	        </span>
183	        <div style={{ display: 'flex', gap: 4, padding: 3, borderRadius: 9, background: 'rgba(0,0,0,0.28)', border: '1px solid var(--border-subtle)' }}>
184	          {SPEEDS.map((s) => (
185	            <button key={s} type="button" className={'pill' + (speed === s ? ' active' : '')} onClick={() => setSpeed(s)} title="Playback speed — remembered next time" style={{ padding: '4px 9px', fontSize: 11 }}>{s}×</button>
186	          ))}
187	        </div>
188	      </div>
189	      <div style={{ marginTop: 9, fontSize: 10.5, fontWeight: 600, color: 'var(--text-disabled)' }}>
190	        {fight.video_path.split('/').pop()} · {fps} fps
191	      </div>
192	    </div>
193	  );
194	}
